function validate([root, k]) {
  if (!Array.isArray(root) || root.length === 0 || root[0] === null) return 'The tree needs a root node.';
  let count = 0;
  for (let i = 0; i < root.length; i++) {
    if (i >= 1 + 2 * count) return 'The level-order list has a value with no parent.';
    if (root[i] !== null) count++;
  }
  if (count < 2) return 'The tree needs at least 2 nodes.';
  if (count > 100000) return 'The tree has at most 10^5 nodes.';
  if (root.some(v => v !== null && (!Number.isInteger(v) || v < 1 || v > 1000000))) return 'Every node value is between 1 and 10^6.';
  if (!Number.isInteger(k) || k < 1 || k > count) return 'k is between 1 and the number of nodes.';
  return null;
}

