function kthLargestLevelSum(root, k) {
  const sums = [];
  let level = [root];
  while (level.length > 0) {
    let sum = 0;
    const next = [];
    for (const node of level) {
      sum += node.val;
      if (node.left) next.push(node.left);
      if (node.right) next.push(node.right);
    }
    sums.push(sum);
    level = next;
  }
  if (sums.length < k) return -1;
  sums.sort((a, b) => b - a);
  return sums[k - 1];
}

