function kthLargestLevelSum(root, k) {
  // Depth-first totals per depth, then pick the sum that has fewer than k sums above it but at least k at or above it.
  const totals = [];
  const visit = (node, depth) => {
    if (!node) return;
    totals[depth] = (totals[depth] || 0) + node.val;
    visit(node.left, depth + 1);
    visit(node.right, depth + 1);
  };
  visit(root, 0);
  if (totals.length < k) return -1;
  for (const s of totals) {
    const above = totals.filter(x => x > s).length;
    const atLeast = totals.filter(x => x >= s).length;
    if (above < k && k <= atLeast) return s;
  }
  return -1;
}

