function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 900 + Math.floor(rand() * 100) : 2 + Math.floor(rand() * 11);
  const mode = rand();
  // Values span the whole range, or a tiny range so that level sums often tie.
  const value = () => large && mode < 0.6 || mode < 0.3 ? 1 + Math.floor(rand() * 1000000) : 1 + Math.floor(rand() * 4);
  // Some trees start with a long downward chain, which makes many levels.
  const chain = large ? (rand() < 0.4 ? 100 + Math.floor(rand() * 300) : 1) : (rand() < 0.25 ? n : 1);
  const nodes = [{ val: value(), left: null, right: null, depth: 0 }];
  for (let i = 1; i < chain; i++) {
    nodes[i - 1][rand() < 0.5 ? 'left' : 'right'] = i;
    nodes.push({ val: value(), left: null, right: null, depth: i });
  }
  const slots = [[chain - 1, 'left'], [chain - 1, 'right']];
  for (let i = chain; i < n; i++) {
    const pickAt = Math.floor(rand() * slots.length);
    const [parent, side] = slots[pickAt];
    slots[pickAt] = slots[slots.length - 1];
    slots.pop();
    nodes[parent][side] = i;
    nodes.push({ val: value(), left: null, right: null, depth: nodes[parent].depth + 1 });
    slots.push([i, 'left'], [i, 'right']);
  }
  const levels = 1 + Math.max(...nodes.map(node => node.depth));
  // Level-order serialisation with null for missing children, trailing nulls removed.
  const out = [];
  const queue = [0];
  for (let q = 0; q < queue.length; q++) {
    if (queue[q] === null) { out.push(null); continue; }
    const node = nodes[queue[q]];
    out.push(node.val);
    queue.push(node.left, node.right);
  }
  while (out.length && out[out.length - 1] === null) out.pop();
  // Usually k names an existing level; sometimes it runs past the last one.
  const k = rand() < 0.8 ? 1 + Math.floor(rand() * levels) : Math.min(n, levels + 1 + Math.floor(rand() * 3));
  return [out, k];
}
